'use client';
const require_dropdown = require("./dropdown.cjs");
const require_dropdown_button = require("./dropdown-button.cjs");
const require_dropdown_heading = require("./dropdown-heading.cjs");
const require_dropdown_item = require("./dropdown-item.cjs");
const require_dropdown_list = require("./dropdown-list.cjs");
const require_dropdown_trigger = require("./dropdown-trigger.cjs");
const require_dropdown_trigger_context = require("./dropdown-trigger-context.cjs");
//#region src/components/dropdown/index.ts
/**
* Dropdown component, used to display a list of options.
*
* @example with TriggerContext
* <Dropdown.TriggerContext>
*   <Dropdown.Trigger>Dropdown trigger</Dropdown.Trigger>
*   <Dropdown placement='bottom-end'>
*     <Dropdown.Heading>Dropdown</Dropdown.Heading>
*     <Dropdown.List>
*       <Dropdown.Item>
*         <Dropdown.Button>Option</Dropdown.Button>
*       </Dropdown.Item>
*     </Dropdown.List>
*   </Dropdown>
* </Dropdown.TriggerContext>
*
* @example without TriggerContext
* <Button popovertarget="my-dropdown">Trigger</Button>
* <Dropdown id="my-dropdown">
*   <Dropdown.Heading>Heading</Dropdown.Heading>
*   <Dropdown.List>
*     <Dropdown.Item>
*       <Dropdown.Button>Item</Dropdown.Button>
*     </Dropdown.Item>
*   </Dropdown.List>
* </Dropdown>
*/
const DropdownComponent = Object.assign(require_dropdown.Dropdown, {
	TriggerContext: require_dropdown_trigger_context.DropdownTriggerContext,
	Heading: require_dropdown_heading.DropdownHeading,
	List: require_dropdown_list.DropdownList,
	Item: require_dropdown_item.DropdownItem,
	Button: require_dropdown_button.DropdownButton,
	Trigger: require_dropdown_trigger.DropdownTrigger
});
DropdownComponent.TriggerContext.displayName = "Dropdown.TriggerContext";
DropdownComponent.List.displayName = "Dropdown.List";
DropdownComponent.Heading.displayName = "Dropdown.Heading";
DropdownComponent.Item.displayName = "Dropdown.Item";
DropdownComponent.Button.displayName = "Dropdown.Button";
DropdownComponent.Trigger.displayName = "Dropdown.Trigger";
//#endregion
exports.Dropdown = DropdownComponent;
exports.DropdownButton = require_dropdown_button.DropdownButton;
exports.DropdownHeading = require_dropdown_heading.DropdownHeading;
exports.DropdownItem = require_dropdown_item.DropdownItem;
exports.DropdownList = require_dropdown_list.DropdownList;
exports.DropdownTrigger = require_dropdown_trigger.DropdownTrigger;
exports.DropdownTriggerContext = require_dropdown_trigger_context.DropdownTriggerContext;
